/**
 * Exo BiCG driver: mirrors PolyBench/C bicg.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"

/* Include the Exo-generated kernel header. */
#include "generated/bicg/bicg.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Heuristically chosen tile size along the inner (j) dimension.
# This improves cache behavior on A and p and, after unrolling,
# exposes a long, straight-line inner loop for the C compiler
# to auto-vectorize.
J_TILE = 32


@proc
def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # Initialize s over its m entries.
    # Separate from the main loop to keep the main kernel tight.
    for j in seq(0, m):
        s[j] = 0.0

    # Main BiCG computation:
    # - q[i] := sum_j A[i, j] * p[j]
    # - s[j] := sum_i r[i] * A[i, j]
    for i in seq(0, n):
        q[i] = 0.0
        for j in seq(0, m):
            s[j] += r[i] * A[i, j]
            q[i] += A[i, j] * p[j]


# ---------------------------------------------------------------------------
# Scheduling: cache-friendly tiling + unrolling of the inner j loop
# ---------------------------------------------------------------------------

# Work on a copy so we can describe the schedule step by step.
_kernel_bicg_sched = kernel_bicg

# Tile the inner j loop of the main (i, j) nest:
#   for i in 0..n:
#     for j in 0..m:
#       ...
#
# becomes
#
#   for i in 0..n:
#     for jo in 0..ceil(m/J_TILE):
#       for ji in 0..J_TILE:
#         j = jo*J_TILE + ji
#         (guarded so j < m when m is not divisible by J_TILE)
j_main = _kernel_bicg_sched.find_loop("j #1")  # second 'j' loop: the one inside the i-loop
_kernel_bicg_sched = divide_loop(
    _kernel_bicg_sched,
    j_main,
    J_TILE,
    ["jo", "ji"],
    tail="guard",
)

# Unroll the innermost ji loop to expose ILP and help auto-vectorization.
ji_loop = _kernel_bicg_sched.find_loop("ji")
_kernel_bicg_sched = unroll_loop(_kernel_bicg_sched, ji_loop)

# Clean up the resulting code (simplify expressions, remove trivial loops/ifs).
_kernel_bicg_sched = simplify(_kernel_bicg_sched)

# Export the optimized version under the canonical name expected by the C driver.
kernel_bicg = _kernel_bicg_sched
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_bicg(/*ctxt=*/NULL, m, n,
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(s),
	      (DATA_TYPE*)POLYBENCH_ARRAY(q),
	      (DATA_TYPE*)POLYBENCH_ARRAY(p),
	      (DATA_TYPE*)POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}

